add(slug="agsa", name="Art Gallery of South Australia", wiki="Art Gallery of South Australia", city="Adelaide", country="Australia", continent="Oceania",
 aliases=["Art Gallery of South Australia"], founded="1881",
 desc="Adelaide's art gallery has a fine collection of Australian art and a wide range of European works from the last five centuries.",
 history="The gallery opened in 1881 and its present building dates from 1900. It runs the Adelaide Biennial of Australian Art.",
 highlights=[])

